// ========================================
// NORMALIZADOR UNIVERSAL DE APIs
// Detecta automaticamente: Evolution, UAZAPI, ZAPI
// ========================================

const webhookData = $input.item.json;
let apiType = 'unknown';
let normalizedData = {
  telefone: null,
  mensagem: null,
  fromMe: false,
  messageId: null,
  messageType: null,
  sender_pn: null,
  mediaUrl: null,
  caption: null
};

// ===== EVOLUTION API =====
if (webhookData.body?.data?.key?.remoteJid && webhookData.body?.instance) {
  apiType = 'evolution';
  const msg = webhookData.body.data.message;

  let messageType = webhookData.body.data.messageType || 'conversation';
  let mensagem = msg?.conversation || msg?.extendedTextMessage?.text || msg?.imageMessage?.caption || msg?.documentMessage?.caption || '';
  let caption = msg?.imageMessage?.caption || msg?.documentMessage?.caption || null;

  normalizedData = {
    telefone: webhookData.body.data.key.remoteJid,
    mensagem: mensagem,
    fromMe: webhookData.body.data.key.fromMe || false,
    messageId: webhookData.body.data.key.id,
    messageType: messageType,
    sender_pn: webhookData.body.data.pushName || webhookData.body.data.key.remoteJid,
    caption: caption,
    mediaUrl: null,
    evo_instance: webhookData.body.instance,
    evo_server_url: webhookData.body.server_url,
    evo_apikey: webhookData.body.apikey,
    evo_pushName: webhookData.body.data.pushName,
    evo_timestamp: webhookData.body.data.messageTimestamp,
    body_event: webhookData.body.event || ''
  };
}

// ===== UAZAPI =====
else if (webhookData.body?.message?.chatid && webhookData.body?.BaseUrl) {
  apiType = 'uazapi';
  const msg = webhookData.body.message;

  const rawType = msg.messageType || '';
  const rawTypeLower = rawType.toLowerCase();

  let messageType = 'conversation';
  let mensagem = '';
  let caption = null;
  let mediaUrl = null;

  if (rawTypeLower === 'audiomessage' || msg.mediaType === 'ptt' || msg.mediaType === 'audio') {
    messageType = 'audioMessage';
    mediaUrl = (typeof msg.content === 'object' ? msg.content?.URL : null) || null;
    mensagem = '[Áudio]';
  } else if (rawTypeLower === 'imagemessage' || msg.mediaType === 'image') {
    messageType = 'imageMessage';
    mediaUrl = (typeof msg.content === 'object' ? msg.content?.URL : null) || null;
    caption = msg.text || '';
    mensagem = caption;
  } else if (rawTypeLower === 'documentmessage' || msg.mediaType === 'document') {
    messageType = 'documentMessage';
    mediaUrl = (typeof msg.content === 'object' ? msg.content?.URL : null) || null;
    caption = msg.text || msg.fileName || '';
    mensagem = caption;
  } else if (rawTypeLower === 'stickermessage' || msg.mediaType === 'sticker') {
    messageType = 'stickerMessage';
    mediaUrl = (typeof msg.content === 'object' ? msg.content?.URL : null) || null;
    mensagem = '[Sticker]';
  } else {
    messageType = 'conversation';
    mensagem = (typeof msg.content === 'string' ? msg.content : '') || msg.text || '';
  }

  normalizedData = {
    telefone: msg.chatid,
    mensagem: mensagem,
    fromMe: msg.fromMe || false,
    messageId: msg.messageid || msg.id || null,
    messageType: messageType,
    sender_pn: msg.senderName || msg.sender_pn || msg.chatid,
    caption: caption,
    mediaUrl: mediaUrl,
    uazapi_BaseUrl: webhookData.body.BaseUrl,
    uazapi_token: webhookData.body.token,
    uazapi_owner: webhookData.body.owner,
    uazapi_instanceName: webhookData.body.instanceName,
    uazapi_chatName: webhookData.body.chat?.wa_name || webhookData.body.chat?.name || null,
    body_event: 'messages.upsert'
  };
}

// ===== Z-API =====
else if (webhookData.body?.instanceId && (webhookData.body?.text || webhookData.body?.audio || webhookData.body?.image || webhookData.body?.document || webhookData.body?.sticker)) {
  apiType = 'zapi';
  const body = webhookData.body;

  let messageType = 'conversation';
  let mensagem = '';
  let caption = null;
  let mediaUrl = null;

  if (body.audio) {
    messageType = 'audioMessage';
    mediaUrl = body.audio.audioUrl;
    mensagem = '[Áudio]';
  } else if (body.image) {
    messageType = 'imageMessage';
    caption = body.image.caption || '';
    mediaUrl = body.image.imageUrl;
    mensagem = caption;
  } else if (body.document) {
    messageType = 'documentMessage';
    caption = body.document.caption || body.document.fileName || '';
    mediaUrl = body.document.documentUrl;
    mensagem = caption;
  } else if (body.sticker) {
    messageType = 'stickerMessage';
    mediaUrl = body.sticker.stickerUrl || body.sticker.imageUrl;
    mensagem = '[Sticker]';
  } else if (body.text) {
    messageType = 'conversation';
    mensagem = body.text.message || '';
  }

  normalizedData = {
    telefone: body.phone,
    mensagem: mensagem,
    fromMe: body.fromMe || false,
    messageId: body.messageId || null,
    messageType: messageType,
    sender_pn: body.senderName || body.phone,
    caption: caption,
    mediaUrl: mediaUrl,
    zapi_instanceId: body.instanceId,
    zapi_connectedPhone: body.connectedPhone,
    zapi_token: webhookData.headers?.['z-api-token'] || null,
    zapi_clientToken: null,
    zapi_chatName: body.chatName || null,
    zapi_timestamp: body.momment || null,
    zapi_isGroup: body.isGroup || false,
    zapi_fromApi: body.fromApi || false,
    body_event: 'messages.upsert'
  };
}

return {
  json: {
    ...normalizedData,
    api_type: apiType,
    isGroup: normalizedData.zapi_isGroup || false,
    fromApi: normalizedData.zapi_fromApi || false,
    webhook_completo: webhookData
  }
};

