const items = $input.all();
for (const item of items) {
  if (item.binary && item.binary.data) {
    item.binary.data.fileName = 'audio.ogg';
    item.binary.data.mimeType = 'audio/ogg';
  }
}
return items;

const items = $input.all();
for (const item of items) {
  if (item.binary && item.binary.data) {
    item.binary.data.fileName = 'image.jpg';
    item.binary.data.mimeType = 'image/jpeg';
  }
}
return items;

const items = $input.all();
for (const item of items) {
  if (item.binary && item.binary.data) {
    item.binary.data.fileName = 'documento.pdf';
    item.binary.data.mimeType = 'application/pdf';
  }
}
return items;

const data = $json.mensagem_completa;
const matches = data.match(/\[.*?\]/g);
const arraysUnicos = new Set();
const resultadoFinal = [];
for (const bloco of matches || []) {
  try {
    const array = JSON.parse(bloco);
    const frase = array.join(' ');
    if (!arraysUnicos.has(frase)) {
      arraysUnicos.add(frase);
      resultadoFinal.push(frase);
    }
  } catch (e) { continue; }
}
const mensagem_lead = resultadoFinal.join(' ');
return [{ json: { mensagem_lead } }];

